        createOrder(uniqueUser(), code, p, 1);

        assertProblem(postOrder(uniqueUser(), uniqueKey(), orderBody(code, p, 3)), 409, "COUPON_EXHAUSTED");
        assertThat(product(p).get("reserved").asLong()).isEqualTo(1);
